import string

from math import gcd

ALPHABET = string.ascii_lowercase
M = len(ALPHABET)


def _check_coprime(a):
    if gcd(a, M) != 1:
        raise ValueError("a and m must be coprime.")


def _modular_inverse(a):
    for x in range(M):
        if (a * x) % M == 1:
            return x
    raise ValueError("a and m must be coprime.")


def encode(plain_text, a, b):
    _check_coprime(a)

    encoded = []
    for char in plain_text.lower():
        if char in ALPHABET:
            i = ALPHABET.index(char)
            encoded.append(ALPHABET[(a * i + b) % M])
        elif char.isdigit():
            encoded.append(char)

    # Group the output into fixed-length chunks of 5.
    return " ".join(
        "".join(encoded)[i : i + 5] for i in range(0, len(encoded), 5)
    )


def decode(ciphered_text, a, b):
    _check_coprime(a)
    a_inv = _modular_inverse(a)

    decoded = []
    for char in ciphered_text:
        if char in ALPHABET:
            y = ALPHABET.index(char)
            decoded.append(ALPHABET[(a_inv * (y - b)) % M])
        elif char.isdigit():
            decoded.append(char)

    return "".join(decoded)
